def wronskianMatrix {k : ℕ} (b : Fin k → PowerSeries F) :
    Matrix (Fin k) (Fin k) (PowerSeries F) :=
  fun j l => derivativeIter j.val (b l)

def normalizedWronskianMatrix {k : ℕ} (b : Fin k → PowerSeries F)
    (a : Fin k → ℕ) : Matrix (Fin k) (Fin k) (PowerSeries F) :=
  fun j l => derivativeTail (b l) (a l) j.val

def derivativeMatrix {I : Type*} (k : ℕ) (h : I → PowerSeries F) :
    Matrix (Fin k) I (PowerSeries F) := fun j t => derivativeIter j.val (h t)

omit [CharZero F] in

def coefficient (u : ℕ → PowerSeries k) (N : ℕ → ℕ) (m i : ℕ) : LaurentSeries k :=
  (algebraMap (PowerSeries k) (LaurentSeries k) PowerSeries.X) ^ budget N m /
    algebraMap (PowerSeries k) (LaurentSeries k) (denominator u m i)

def moment (u : ℕ → PowerSeries k) (N : ℕ → ℕ) (m n : ℕ) : LaurentSeries k :=
  ∑ i ∈ Finset.range (m + 1), coefficient u N m i *
    (algebraMap (PowerSeries k) (LaurentSeries k) (u i)) ^ n

def BalancedDistances (u : ℕ → PowerSeries k) (N : ℕ → ℕ) : Prop :=
  ∀ i j l : ℕ, 0 < l →
    ((l : ℕ∞) ≤ (PowerSeries.order (u i - u j)) ↔ i % N l = j % N l)

theorem formalSeries_eq_of_derivative_eq {f g : PowerSeries ℚ}
    (hd : derivative f = derivative g) (hc : constantCoeff f = constantCoeff g) :
    f = g

