def rowCostBound (M d : ℕ) : ℕ :=
  7 * generatorExpressionBudget M + 1 +
    d * (entryCostBound M + loopControlBound M + entryOutputBound M)

def expectedCode (i r q : ℕ) : NCHitting.BitModel.RationalCode :=
  if q < r then ⟨decide ((r - q - 1) % 2 = 1), 1, r * (i + 1) ^ (r - q)⟩
  else ⟨false, 0, 1⟩

theorem eval_one_ne_zero_of_size_le_one {F : Type*} {n : ℕ}
    [Semiring F] [Nontrivial F] (f : Formula F n) (hs : f.size ≤ 1)
    (hf : f.coeff ≠ 0) : f.eval id (fun _ => 1) ≠ 0

def finPencil {n : ℕ} (f : Formula n) :
    Matrix (Fin (Fintype.card f.Index)) (Fin (Fintype.card f.Index)) (Affine.Form n) :=
  (Formula.pencil f).reindex (Fintype.equivFin f.Index) (Fintype.equivFin f.Index)

